    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Bars at corners project their color inward along the corresponding
    # rows/columns. Interior singleton markers are recolored to 4.
    # Use uniform corner bars and extend only through the background cells.
    corner_bars = []
    for r, c, dr, dc in ((0, 0, 0, 1), (0, w - 1, 0, -1),
                         (h - 1, 0, 0, 1), (h - 1, w - 1, 0, -1)):
        color = grid[r][c]
        if color == grid[0][0] and color == grid[h - 1][w - 1]:
            # Not a reliable test for bar color; actual contiguous run determines it.
            pass
        n = 0
        while 0 <= c + n * dc < w and grid[r][c + n * dc] == color:
            n += 1
        if n >= 2 and color != grid[0][0] or n >= 2:
            corner_bars.append((r, c, dr, dc, color, n))
    # Project only the bar's own cells inward, preserving all non-background marks.
    for r, c, dr, dc, color, n in corner_bars:
        for k in range(n):
            rr, cc = r, c + k * dc
            step_r, step_c = (1 if r == 0 else -1), 0
            if dc != 0:
                step_r, step_c = 0, (1 if c == 0 else -1)
            y, x = rr + step_r, cc + step_c
            while 0 <= y < h and 0 <= x < w:
                if grid[y][x] != grid[0][0]:
                    break
                out[y][x] = color
                y += step_r
                x += step_c
    # Recolor isolated non-background interior markers (not part of bars).
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] != grid[0][0] and counts[grid[r][c]] == 1:
                out[r][c] = 4
    return out
